package com.example;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class App {

    private static final Logger log = LoggerFactory.getLogger(App.class);

    public static void main(String[] args) {
        log.info("Application starting");

        Greeter greeter = new Greeter();
        log.debug("Created greeter {}", greeter);
        System.out.println(greeter.greet("World"));

        log.info("Application finished");
    }
}

package com.example;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class Greeter {

    private static final Logger log = LoggerFactory.getLogger(Greeter.class);

    public String greet(String name) {
        log.trace("greet() called with name={}", name);
        if (name == null || name.isBlank()) {
            log.warn("Blank name supplied, falling back to default");
            name = "stranger";
        }
        String message = "Hello, " + name + "!";
        log.debug("Returning message: {}", message);
        return message;
    }
}

package com.example;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

class GreeterTest {

    private final Greeter greeter = new Greeter();

    @Test
    void greetsByName() {
        assertEquals("Hello, World!", greeter.greet("World"));
    }

    @Test
    void fallsBackWhenNameIsBlank() {
        assertEquals("Hello, stranger!", greeter.greet("  "));
    }
}

